contract InvMutTest is Test {
    VaultAdapter c;
    function setUp() public { c = new VaultAdapter(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        bytes32 expectedSlot = 0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;
        vm.prank(caller);
        bytes32 actualSlot = c.proxiableUUID();
        assertTrue(actualSlot == expectedSlot);
    }
}
